import {GADGETS} from './engine.js';
import {FarmSaveStore} from './save-store.js';
import {installFarmManagement} from './management-ui.js';
import {CROPS,PLACES} from './colony.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

// The colony systems mount into the HUD: save and speed by the system buttons, alerts and the
// campaign with the objectives, squad orders in the command card, automatic planting status in the Fields panel.
// Expeditions are sent from the Operations board; this module only handles the decision on site.
export function installColonyUI({game,selected,selectOnly,lookAt,notice,sync,focusGame,setPlacing,keys,start,afterLoad}){
 const $=id=>document.getElementById(id);let speed=1,patrolPick=false,lastSync=0,pausedForDialog=false,missionDecisionId=null,loading=false;
 const nav=document.createElement('div');nav.className='colony-tools';nav.innerHTML='<button id="colony-save" type="button" title="Save (Ctrl+S)">Save</button><button id="colony-load" type="button">Saves</button><button id="colony-speed" type="button" aria-label="Set double game speed">1×</button>';$('hud-system-tools').prepend(nav);
 const campaign=$('campaign-btn');
 const resume=$('continue-save');
 const introNote=document.querySelector('.intro-note');if(introNote)introNote.textContent='CLASSIC · ENDLESS · RADIO CAMPAIGN';
 $('hud-colony-objectives').innerHTML='<p id="colony-forecast" class="hud-forecast"></p><div id="colony-alerts" class="hud-alerts" role="status" aria-live="polite"></div><details id="colony-tutorial" class="hud-tutorial" open><summary>YOUR FIRST DAY</summary><div id="tutorial-steps" class="tutorial-steps"></div><button id="tutorial-dismiss" class="text-button" type="button">Dismiss</button></details><div id="colony-campaign" class="campaign-card" hidden></div><p id="colony-save-status" class="hud-forecast" role="status" aria-live="polite">Autosaves each morning</p>';
 $('hud-squad').innerHTML='<div class="squad-buttons"><button type="button" id="colony-patrol" title="Patrol between here and a point you click">Patrol</button><button type="button" id="colony-guard" title="Hold this position">Guard</button><button type="button" id="colony-retreat" title="Retreat into the farmhouse">Retreat</button><button type="button" id="colony-clinic" title="Send to the clinic">Clinic</button></div><label class="squad-fire">FIRE <select id="colony-fire" aria-label="Fire discipline"><option value="normal">Attack nearby enemies</option><option value="conserve">Conserve shells</option><option value="hold">Hold fire</option></select></label><p id="colony-people" class="squad-person"></p>';
 $('hud-fields').innerHTML='<p id="crop-summary" class="pop-note"></p><div id="crop-grid" class="crop-grid"></div><p class="pop-note">Farmers plant automatically using your Crops upgrade level. Upgrade Crops in Build for corn, faster growth, then pumpkins. Expand the field for more plots.</p><span id="colony-hay"></span><div class="colony-actions"><button id="colony-gate-build" type="button">Place a gate · '+GADGETS.gate.cost+' scrap</button><button id="colony-gates-open" type="button">Open all gates</button><button id="colony-gates-close" type="button">Close all gates</button></div><div id="gate-list"></div><p id="perimeter-status" class="pop-note"></p><button id="perimeter-repair" type="button">Restore boundary</button><p class="pop-note">Scouts use the south gate; it opens for passing teams, then closes. The boundary does not use your 60 custom-defense slots.</p>';
 const dialog=document.createElement('dialog');dialog.id='expedition-dialog';dialog.className='help-dialog colony-dialog';dialog.setAttribute('aria-labelledby','expedition-title');dialog.innerHTML='<div class="help-modal"><button id="expedition-close" class="icon-button modal-close" type="button" aria-label="Close">×</button><p class="eyebrow">BEYOND THE FARM</p><h2 id="expedition-title">The team has arrived</h2><div id="expedition-content"></div><p id="expedition-message" role="status"></p></div>';document.body.append(dialog);
 let storage;try{storage=localStorage;}catch{}const store=new FarmSaveStore(storage);const readSave=()=>store.latest();
 function save(auto=false){if(['title','won','gameover'].includes(game.s.mode))return false;try{store.write(game.serialize(),auto?'auto':'manual-1');$('colony-save-status').textContent=`${auto?'Autosaved':'Saved'} · day ${game.s.day}`;resume.hidden=false;describeSave();if(!auto)notice('Farm saved in this browser.');return true;}catch{$('colony-save-status').textContent='Storage unavailable';if(!auto)notice('The browser could not store this save.');return false;}}
 const describeSave=()=>{try{const raw=readSave(),save=raw&&JSON.parse(raw);if(save?.s){const s=save.s;$('continue-detail').textContent=`Day ${s.day} · ${s.campaign?'radio campaign':s.endless?'endless':'story'} · ${s.people?.length||0} people`;}}catch{}};resume.hidden=!readSave();describeSave();const savedFarms=$('saved-farms');savedFarms.addEventListener('click',()=>management.open('saves'));
 const previousEvent=game.onEvent;game.onEvent=e=>{previousEvent(e);if(e.type==='autosave'&&!loading)save(true);};
 function load(raw=readSave()){if(!raw){notice('There is no saved farm in this browser yet.');return;}loading=true;pausedForDialog=false;document.querySelectorAll('dialog[open]').forEach(d=>d.close());const result=game.restore(raw);loading=false;if(result.error){notice(result.error);return;}document.querySelectorAll('dialog[open]').forEach(d=>d.close());selected.clear();keys.clear();setPlacing(null);$('intro-overlay').hidden=true;lookAt(700,330);afterLoad?.();sync();refresh(true);focusGame();notice(`Loaded day ${game.s.day}. ${game.s.mode==='paused'?'Resume when you are ready.':'Your morning is ready.'}`);}
 $('colony-save').addEventListener('click',()=>save());$('colony-load').addEventListener('click',()=>management.open('saves'));resume.addEventListener('click',()=>load());campaign.addEventListener('click',()=>start(false,true));
 $('colony-speed').addEventListener('click',()=>{speed=speed===1?2:1;$('colony-speed').textContent=`${speed}×`;$('colony-speed').classList.toggle('active',speed===2);$('colony-speed').setAttribute('aria-label',speed===1?'Set double game speed':'Set normal game speed');notice(speed===2?'Double speed.':'Normal speed.');});
 window.addEventListener('keydown',e=>{if(!['playing','paused'].includes(game.s.mode)||document.querySelector('dialog[open]')||e.target instanceof HTMLSelectElement)return;if(e.key==='Escape'&&patrolPick){patrolPick=false;notice('Patrol placement cancelled.');}const n=Number(e.key);if(n>=1&&n<=4&&(e.ctrlKey||e.altKey)){e.preventDefault();e.stopImmediatePropagation();if(e.ctrlKey){game.saveGroup(n,[...selected]);notice(`Group ${n} saved (${selected.size} people).`);}else{selectOnly(game.group(n));notice(`Group ${n} selected.`);}sync();}if(e.key.toLowerCase()==='s'&&e.ctrlKey){e.preventDefault();e.stopImmediatePropagation();save();}},true);
 $('colony-patrol').addEventListener('click',()=>{if(!selected.size){notice('Select a patrol team first.');return;}patrolPick=true;setPlacing(null);notice('Click an open destination. The squad will patrol between there and its current position.');focusGame();});
 $('colony-guard').addEventListener('click',()=>{game.holdPosition([...selected]);notice('The selected squad is holding its position.');sync();});
 $('colony-retreat').addEventListener('click',()=>{if(!selected.size){notice('Select people to retreat first.');return;}game.retreat([...selected]);sync();});
 $('colony-clinic').addEventListener('click',()=>{if(!selected.size){notice('Select a patient first.');return;}if(!game.sendToClinic([...selected]))notice('Build a clinic and assign a medic first.');sync();});
 $('colony-fire').addEventListener('change',e=>{if(!selected.size){notice('Select people before changing fire discipline.');return;}game.setFireMode([...selected],e.target.value);sync();});
 $('tutorial-dismiss').addEventListener('click',()=>{game.s.tutorial=false;refresh(true);});
 $('perimeter-repair').addEventListener('click',()=>game.restorePerimeter());$('colony-gate-build').addEventListener('click',()=>setPlacing('gate'));$('colony-gates-open').addEventListener('click',()=>{game.setGates(true);notice('Gates open. Zombies can walk through the entrance.');});$('colony-gates-close').addEventListener('click',()=>{game.setGates(false);notice('Gates closed.');});
 dialog.addEventListener('click',e=>{const choice=e.target.closest('[data-choice]');if(choice){game.expeditionChoice(choice.dataset.choice);missionDecisionId=null;dialog.close();}});
 $('expedition-close').addEventListener('click',()=>{if(missionDecisionId){game.expeditionChoice('return');missionDecisionId=null;}dialog.close();});
 dialog.addEventListener('cancel',()=>{if(missionDecisionId){game.expeditionChoice('return');missionDecisionId=null;}});
 dialog.addEventListener('close',()=>{if(pausedForDialog&&game.s.mode==='paused')game.resume();pausedForDialog=false;sync();});
 function openDecision(m){if(document.querySelector('dialog[open]'))return;missionDecisionId=m.id;pausedForDialog=game.s.mode==='playing';if(pausedForDialog)game.pause();const p=PLACES[m.place];$('expedition-title').textContent=`Inside ${p.name.toLowerCase()}`;$('expedition-message').textContent='';$('expedition-content').innerHTML=`<p class="help-intro">The team found usable supplies and someone hiding nearby. Choose how they spend their remaining time.</p><div class="expedition-choice"><button type="button" data-choice="rescue"><strong>Rescue a survivor</strong><span>Bring someone home with normal supplies. Farmhouse capacity: ${game.s.people.length}/8.</span></button><button type="button" data-choice="loot"><strong>Search deeper</strong><span>60% more loot. Injury risk rises to ${Math.round((m.risk+.15)*100)}%.</span></button><button type="button" data-choice="return"><strong>Return with what you found</strong><span>Normal supplies, lowest risk (${Math.round(m.risk*100)}%). Home in ${Math.ceil(p.time*.55)}s.</span></button></div>`;dialog.showModal();sync();}
 function refresh(force=false){const now=performance.now();if(!force&&now-lastSync<400)return;lastSync=now;const s=game.s,active=['playing','paused'].includes(s.mode);$('colony-save').disabled=['title','won','gameover'].includes(s.mode);$('colony-load').disabled=false;
  $('hud-weather').textContent=`${s.weather.toUpperCase()}${s.weather==='rain'?' · TANKS FILL':s.weather==='dry'?' · DRY':s.weather==='fog'?' · LOW VISIBILITY':''}`;$('colony-forecast').textContent=s.forecast||s.phase==='night'?game.nightBrief():'Send a scout for a horde forecast.';
  const alerts=active?game.alerts():[];$('colony-alerts').hidden=!alerts.length;const alertHtml=alerts.map(a=>`<span>⚠ ${esc(a)}</span>`).join('');if($('colony-alerts').dataset.html!==alertHtml){$('colony-alerts').dataset.html=alertHtml;$('colony-alerts').innerHTML=alertHtml;}
  $('colony-tutorial').hidden=!s.tutorial||s.mode==='title'||s.day>1;const steps=game.tutorialSteps().map(a=>`<span class="${a.done?'done':''}">${a.done?'✓':'○'} ${a.text}</span>`).join('');if($('tutorial-steps').dataset.html!==steps){$('tutorial-steps').dataset.html=steps;$('tutorial-steps').innerHTML=steps;}
  const people=s.people.filter(p=>selected.has(p.id));$('hud-squad').hidden=!people.length||!active;if(people.length&&document.activeElement!==$('colony-fire'))$('colony-fire').value=people[0].fireMode;
  const top=p=>Object.entries(p.skills).map(([k])=>[k,game.skill(p,k)]).filter(([,lv])=>lv>0).map(([k,lv])=>`${k} ${lv}`).join(' · ')||'no skills yet';
  $('colony-people').innerHTML=people.length===1?`<strong>${esc(people[0].name)}</strong> · ${people[0].traits.good} / ${people[0].traits.weak} · morale ${Math.round(people[0].morale)} · ${top(people[0])}${people[0].orders.length?` · ${people[0].orders.length} queued`:''}`:people.length?`${people.length} people · Ctrl+1–4 saves this group, Alt+1–4 recalls it`:'';
  $('colony-hay').textContent=game.level('barn')?`Hay ${s.hay}/${game.stat('barn','hay')}.`:'';
  const crop=game.cropName();$('crop-summary').textContent='AUTO PLANTING · '+crop.toUpperCase()+' · Crops level '+s.upgrades.crops+' · '+s.plots.length+' plots';
  $('crop-grid').innerHTML=s.plots.map((p,i)=>'<div class="plot-readout"><strong>Plot '+(i+1)+'</strong><span>'+(p.growth<0?'Empty · waiting for planting':p.growth>=1?'Ready to harvest':Math.ceil((1-p.growth)*game.growTimeFor(p))+'s to harvest')+'</span></div>').join('');
  $('gate-list').innerHTML=s.fences.filter(g=>g.kind==='gate').map((g,i)=>'<button type="button" data-gate="'+g.id+'">'+(g.perimeter?'Scouting gate':'Gate '+(i+1))+' · '+(g.open?'Open → close':'Closed → open')+'</button>').join('');
  const perimeter=game.perimeterStatus();$('perimeter-status').textContent=perimeter.missing+' boundary gaps · '+perimeter.damaged+' damaged sections · '+perimeter.waiting+' rebuilds queued';$('perimeter-repair').textContent=perimeter.cost?'Queue boundary repairs · '+perimeter.cost+' scrap':'Boundary maintained';$('perimeter-repair').disabled=!active||!perimeter.cost||s.scrap<perimeter.cost;const m=s.missions.find(m=>m.stage!=='done');
  $('colony-campaign').hidden=!s.campaign&&!m;$('colony-campaign').innerHTML=`${s.campaign?`<strong>THE RADIO CAMPAIGN</strong><p>${s.radioContact?'✓ Signal received':'○ Build the radio receiver, recover a component, then repair its aerial.'}</p><p>${s.day>=10?'Final siege is here.':'Survive through the day-10 siege.'} ${s.campaignWon?'✓ Settlement secured':''}</p><small>Day ${s.day}/10 · ${s.components} radio components</small>`:''}${m?`<p>Expedition · ${PLACES[m.place].name} · ${m.stage==='decision'?'awaiting your decision':`${m.stage==='travel'?'outbound':'returning'} · ${Math.ceil(Math.max(0,m.remaining))}s`}</p>`:''}`;
  for(const id of ['colony-patrol','colony-guard','colony-retreat','colony-clinic'])$(id).disabled=!active||!people.length;for(const id of ['colony-gate-build','colony-gates-open','colony-gates-close'])$(id).disabled=!active;
  if(s.campaign){$('mode-label').hidden=false;$('mode-label').textContent='CAMPAIGN';$('survive-label').textContent='Contact the settlement · survive 10 nights';document.querySelector('#goal-survive .goal-counter').textContent=`${s.mode==='won'?10:Math.max(0,s.day-1)}/10`;if(s.mode==='won'){$('state-eyebrow').textContent='SIGNAL RECEIVED. FARM SECURED.';$('state-title').textContent='You are not alone.';$('state-description').textContent=`You contacted another settlement and led your people through the final siege. ${s.kills} zombies stopped, ${s.missionHistory.length} expeditions completed.`;}}
  if(s.mode==='wheel'&&s.wheel?.result&&$('wheel-dialog').open){$('wheel-result').textContent=s.wheel.result.text;$('wheel-spin').hidden=true;$('wheel-continue').hidden=false;}
  if(m?.stage==='decision'&&!dialog.open&&active)openDecision(m);
 }
 const management=installFarmManagement({game,store,load,selected,notice,sync,focusGame});
 $('gate-list').addEventListener('click',e=>{const b=e.target.closest('[data-gate]');if(b){const g=game.s.fences.find(g=>g.id===Number(b.dataset.gate));if(g)game.setGate(g.id,!g.open);refresh(true);}});
 return {refresh,speed:()=>speed,command(at,queued){if(patrolPick){patrolPick=false;game.setPatrol([...selected],at.x,at.y);notice('Patrol route assigned.');sync();return {type:'patrol',text:'Patrol route assigned.'};}return game.command([...selected],at.x,at.y,queued);}};
}
